I've reviewed the repository. The site is a well-structured public documentation of an autonomous agent project. However, I found a real bug in `site/app.js`: three functions are called but never defined — `id` (used throughout `init`), `timeAgo` (used in `refreshLiveStatus` and `renderStats`), and `updateNextWakeNotes` (called in `refreshLiveStatus`). Since `check.sh` only runs syntax checks (`node --check`), these runtime `ReferenceError`s slip through and silently break the copy buttons, the last-wake time-ago display, and the live status refresh.

Let me fix these by adding the missing definitions.

```file:site/app.js
// Momento app.js – core site logic
// All functions are scoped to avoid globals unless needed for testing

// Stats snapshot (last_update) is refreshed every 5 minutes; last_wake may be older.
// The freshness indicator reflects the snapshot age, not the live clock.
const WAKES_PER_DAY = 16;
const INTERVAL_MINUTES = 90;
const START_DATE = new Date('2026-08-05T00:07:00Z'); // first wake UTC
const STATS_REFRESH_MS = 5 * 60 * 1000; // refresh stats every 5 minutes
const INTERVAL_MS = INTERVAL_MINUTES * 60 * 1000; // interval in milliseconds, reused across time math

// ---------- State ----------
let stats = {};
let recentTweaks = [];
let isClient = typeof window !== 'undefined';
const copyFeedbackTimers = new WeakMap();
const id = (s) => document.getElementById(s);

// ---------- Stats & Data Loading ----------
async function loadStats() {
  const dataStatusEl = document.getElementById('data-status');
  try {
    const res = await fetch('stats.json', { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    stats = await res.json();
    if (dataStatusEl) dataStatusEl.textContent = 'Live';
    renderStats();
  } catch (e) {
    if (dataStatusEl) dataStatusEl.textContent = 'Unavailable';
    console.error('Failed to load stats:', e);
  }
}

// ---------- Time Calculations ----------
function nextWakeTime() {
  const now = Date.now();
  const elapsed = now - START_DATE.getTime();
  const cycles = Math.floor(elapsed / INTERVAL_MS);
  return new Date(START_DATE.getTime() + (cycles + 1) * INTERVAL_MS);
}

function formatUTC(date) {
  const pad = n => n.toString().padStart(2, '0');
  return `${date.getUTCHours()}:${pad(date.getUTCMinutes())} UTC`;
}

function formatUTCDate(date) {
  const opts = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' };
  return date.toLocaleDateString('en-US', opts);
}

