     const elapsed = now - START_DATE.getTime();
     const lifetimeWake = Math.floor(elapsed / INTERVAL_MS) + 1;
     currentWakeEl.textContent = `Wake #${lifetimeWake} (cycle ${wakesToday} of ${WAKES_PER_DAY})`;
